function testRegex(){
  const pattern=document.getElementById('patternInput').value;
  const test=document.getElementById('testInput').value;
  const replace=document.getElementById('replaceInput').value;
  const flagG=document.getElementById('flagG').checked?'g':'';
  const flagI=document.getElementById('flagI').checked?'i':'';
  const flagM=document.getElementById('flagM').checked?'m':'';
  const flagS=document.getElementById('flagS').checked?'s':'';
  const flags=flagG+flagI+flagM+flagS;
  const result=document.getElementById('resultDisplay');

  if(!pattern){result.textContent='Enter a pattern to match';return}

  try{
    const regex=new RegExp(pattern,flags||'g');
    const matches=[...test.matchAll(regex)];
    const matchCount=matches.length;

    // Count unique groups
    const groups=new Set();
    matches.forEach(m=>{for(let i=1;i<m.length;i++)if(m[i]!==undefined)groups.add(i)});

    // Highlighted text
    let lastIdx=0,html='';
    if(flagG||true){
      const globalRegex=new RegExp(pattern,flags||'g');
      let m;
      while((m=globalRegex.exec(test))!==null){
        html+=escapeHTML(test.slice(lastIdx,m.index));
        html+=`<span class="match">${escapeHTML(m[0])}</span>`;
        lastIdx=globalRegex.lastIndex;
        if(lastIdx===m.index)globalRegex.lastIndex++;
      }
      html+=escapeHTML(test.slice(lastIdx));
    }

    // Replace
    let replaceText='';
    if(replace){
      try{replaceText=test.replace(new RegExp(pattern,flags||'g'),replace)}catch(e){replaceText='Replace error'}
    }

    result.innerHTML=html||escapeHTML(test);
    document.getElementById('matchCount').textContent=matchCount;
    document.getElementById('groupCount').textContent=groups.size||0;
    document.getElementById('replaceResult').textContent=replaceText.slice(0,100)+(replaceText.length>100?'...':'')||'-';
    saveToStorage();
  }catch(e){
    result.innerHTML=`<span style="color:#f87171">❌ ${escapeHTML(e.message)}</span>`;
  }
}

function escapeHTML(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}

function saveToStorage(){try{localStorage.setItem('regex_data',JSON.stringify({p:document.getElementById('patternInput').value,t:document.getElementById('testInput').value,r:document.getElementById('replaceInput').value}))}catch(e){}}
function loadFromStorage(){try{const d=JSON.parse(localStorage.getItem('regex_data'));if(d&&d.p){document.getElementById('patternInput').value=d.p;document.getElementById('testInput').value=d.t||'';document.getElementById('replaceInput').value=d.r||'';return true}}catch(e){}return false}
loadFromStorage();testRegex();

