  decrement:{description:'Unary Decrement (subtract 1)','q0':{'0':['0','L','q1'],'1':['1','R','q0'],'_':['_','L','q3']},'q1':{'0':['1','L','q2'],'1':['0','L','q2'],'_':['_','L','q3']},'q2':{'0':['0','L','q2'],'1':['1','L','q2'],'_':['_','L','q3']},'q3':{}},
  doubler:{description:'Unary Doubler','q0':{'1':['x','R','q1'],'0':['0','R','q0'],'_':['_','L','q4']},'q1':{'1':['1','R','q1'],'0':['0','R','q1'],'_':['_','L','q2']},'q2':{'1':['1','L','q2'],'0':['0','L','q2'],'x':['1','R','q3']},'q3':{'1':['1','L','q3'],'0':['0','L','q3'],'_':['_','R','q0']},'q4':{'0':['0','L','q4'],'x':['1','L','q4'],'_':['_','R','q5']},'q5':{'1':['1','R','q5'],'_':['_','R','q6']},'q6':{}},
