};

function loadPreset(name){
  const p=PRESETS[name];if(!p)return;
  program=p;
  tape=[1,1,0,1];head=1;state='q0';steps=0;
  running=false;clearInterval(timer);
  document.getElementById('statusDisplay').textContent='Loaded: '+p.description;
  render();saveToStorage();
}

function getTape(i){return tape[i]!==undefined?tape[i]:'_'}
function setTape(i,v){tape[i]=v}

function step(){
  if(!program[state]){document.getElementById('statusDisplay').textContent='⏹ Halted';return}
  const symbol=getTape(head);
  const instr=program[state][String(symbol)];
  if(!instr){document.getElementById('statusDisplay').textContent='⏹ Halted (no transition)';return}
  const[write,move,nextState]=instr;
  if(write!=='_')setTape(head,parseInt(write)||write);else delete tape[head];
  head+=move==='R'?1:-1;
  if(head<0){head=0;tape.unshift('_')}
  state=nextState;
  steps++;
  render();
  if(!program[state]||!program[state][String(getTape(head))]){document.getElementById('statusDisplay').textContent='✅ Halted';saveToStorage();return true}
  return false;
}

function run(){
  if(running)return;running=true;
  const speed=parseInt(document.getElementById('speedSlider').value);
  document.getElementById('statusDisplay').textContent='▶ Running...';
  timer=setInterval(()=>{const halted=step();if(halted||!running){clearInterval(timer);running=false;document.getElementById('statusDisplay').textContent=halted?'✅ Halted':'⏹ Stopped';saveToStorage()}},Math.max(10,1000-speed));
}

function stop(){running=false;clearInterval(timer);document.getElementById('statusDisplay').textContent='⏹ Stopped'}
function reset(){tape=[1,1,0,1];head=1;state='q0';steps=0;running=false;clearInterval(timer);render();document.getElementById('statusDisplay').textContent='Reset';saveToStorage()}

function render(){
  const tapeEl=document.getElementById('tape');tapeEl.innerHTML='';
  const minIdx=Math.max(0,head-10),maxIdx=head+10;
  for(let i=minIdx;i<=maxIdx;i++){
    const cell=document.createElement('div');cell.className='cell'+(i===head?' head':'');
    cell.textContent=getTape(i);tapeEl.appendChild(cell);
  }
  document.getElementById('stateDisplay').textContent=state;
  document.getElementById('headDisplay').textContent=head;
  document.getElementById('stepDisplay').textContent=steps;

  // Program display
  const progEl=document.getElementById('programDisplay');
  let html='<div style="color:#888;margin-bottom:4px;font-family:Segoe UI,Arial,sans-serif;font-size:0.55rem">Transition Table:</div>';
  for(const[s,transitions]of Object.entries(program)){
    for(const[symbol,[write,move,next]]of Object.entries(transitions)){
      const active=s===state&&String(getTape(head))===symbol;
      html+=`<div class="line${active?' active':''}">${active?'▶ ':''}δ(${s}, ${symbol}) → (${write}, ${move}, ${next})</div>`;
    }
  }
  progEl.innerHTML=html;
}

function saveToStorage(){try{localStorage.setItem('turing_state',JSON.stringify({tape,head,state,steps}))}catch(e){}}
function loadFromStorage(){try{const d=JSON.parse(localStorage.getItem('turing_state'));if(d&&d.tape){tape=d.tape;head=d.head;state=d.state;steps=d.steps||0;return true}}catch(e){}return false}
if(!loadFromStorage())loadPreset('increment');
render();

