}

function applyAdjustments(){
  if(!originalData)return;
  const w=canvas.width,h=canvas.height;
  const data=new Uint8ClampedArray(originalData.data);
  const a=adjustments;
  a.brightness=parseInt(document.getElementById('adjBrightness').value);
  a.contrast=parseInt(document.getElementById('adjContrast').value);
  a.saturation=parseInt(document.getElementById('adjSaturation').value);
  a.exposure=parseInt(document.getElementById('adjExposure').value);
  a.vibrance=parseInt(document.getElementById('adjVibrance').value);
  a.blur=parseInt(document.getElementById('adjBlur').value);

  document.getElementById('adjBrightnessVal').textContent=a.brightness;
  document.getElementById('adjContrastVal').textContent=a.contrast;
  document.getElementById('adjSaturationVal').textContent=a.saturation;
  document.getElementById('adjExposureVal').textContent=a.exposure;
  document.getElementById('adjVibranceVal').textContent=a.vibrance;
  document.getElementById('adjBlurVal').textContent=a.blur;

  for(let i=0;i<data.length;i+=4){
    let r=data[i],g=data[i+1],b=data[i+2];

    // Brightness
    r+=a.brightness*2.55;g+=a.brightness*2.55;b+=a.brightness*2.55;

    // Contrast
    const cf=(100+a.contrast)/100;
    r=(r-128)*cf+128;g=(g-128)*cf+128;b=(b-128)*cf+128;

    // Exposure
    const ef=Math.pow(2,a.exposure/50);
    r*=ef;g*=ef;b*=ef;

    // Saturation
    const gray=0.299*r+0.587*g+0.114*b;
    const sf=(100+a.saturation)/100;
    r=gray+(r-gray)*sf;g=gray+(g-gray)*sf;b=gray+(b-gray)*sf;

    // Vibrance
    if(a.vibrance!==0){
      const max=Math.max(r,g,b);const min=Math.min(r,g,b);
      const sat=max-min;const vf=1+a.vibrance/200;
      if(sat<50){
        r=gray+(r-gray)*vf;g=gray+(g-gray)*vf;b=gray+(b-gray)*vf;
      }
    }

    data[i]=Math.min(255,Math.max(0,r));
    data[i+1]=Math.min(255,Math.max(0,g));
    data[i+2]=Math.min(255,Math.max(0,b));
  }

  // Blur
  if(a.blur>0){/* simplified - skip complex blur for adjustment live preview */}

  currentData=data;
  const imgData=new ImageData(new Uint8ClampedArray(data),w,h);
  ctx.putImageData(imgData,0,0);
  drawHistogram();
}

function applyFilter(type){
  if(!originalData)return;
  resetSliders();
  const w=canvas.width,h=canvas.height;
  const data=new Uint8ClampedArray(originalData.data);

  switch(type){
    case 'grayscale':
      for(let i=0;i<data.length;i+=4){
        const g=0.299*data[i]+0.587*data[i+1]+0.114*data[i+2];
        data[i]=data[i+1]=data[i+2]=g;
      }
      break;
    case 'sepia':
      for(let i=0;i<data.length;i+=4){
        const r=data[i],g=data[i+1],b=data[i+2];
        data[i]=Math.min(255,r*0.393+g*0.769+b*0.189);
        data[i+1]=Math.min(255,r*0.349+g*0.686+b*0.168);
        data[i+2]=Math.min(255,r*0.272+g*0.534+b*0.131);
      }
      break;
    case 'invert':
      for(let i=0;i<data.length;i+=4){data[i]=255-data[i];data[i+1]=255-data[i+1];data[i+2]=255-data[i+2]}
      break;
    case 'vintage':
      for(let i=0;i<data.length;i+=4){
        const r=data[i],g=data[i+1],b=data[i+2];
        data[i]=Math.min(255,r*0.8+g*0.2+b*0.1);
        data[i+1]=Math.min(255,r*0.1+g*0.7+b*0.1);
        data[i+2]=Math.min(255,r*0.1+g*0.1+b*0.6);
        data[i]=Math.min(255,data[i]*0.8+40);
        data[i+1]=Math.min(255,data[i+1]*0.8+20);
        data[i+2]=Math.min(255,data[i+2]*0.8+10);
      }
      break;
    case 'cool':
      for(let i=0;i<data.length;i+=4){data[i]*=0.9;data[i+1]*=0.95;data[i+2]=Math.min(255,data[i+2]*1.1+20)}
      break;
    case 'warm':
      for(let i=0;i<data.length;i+=4){data[i]=Math.min(255,data[i]*1.1+20);data[i+1]*=0.95;data[i+2]*=0.9}
      break;
    case 'sharpen':{
