import { addTask, clearAll, toggleTask, removeTask, render } from '../guilayout/guilayout.ts';

export function renderCLIPrompt(): void {
  const input = prompt('Enter a command: ');
  if (!input) return;
  executeCommand(input);
}

function executeCommand(command: string): void {
  const parts = command.trim().split(/\s+/);
  const name = (parts[0] || '').toLowerCase();
  const arg = Number(parts[1]);
  switch (name) {
    case 'add':
      addTask();
      break;
    case 'done':
      if (!Number.isNaN(arg)) toggleTask(arg);
      break;
    case 'remove':
      if (!Number.isNaN(arg)) removeTask(arg);
      break;
    case 'list':
      render();
      break;
    case 'clear':
      clearAll();
      break;
    default:
      console.log(`Unknown command: ${command}`);
  }
}

