  document.getElementById('startBtn').textContent='▶ Retry';
  document.getElementById('statusDisplay').textContent='💀 Game Over';
  document.getElementById('highScoreDisplay').textContent=highScore;
}

function jump(){if(gameState==='playing'&&player.y>=FLOOR_Y-PLAYER_SIZE-2){player.vy=-12;}}

