function update(){
  if(gameState!=='playing')return;

  // Physics
  const gravity=0.6;
  player.vy+=gravity;
  player.y+=player.vy;
  player.rot+=player.vy*3;

  // Floor
  if(player.y>FLOOR_Y-PLAYER_SIZE){player.y=FLOOR_Y-PLAYER_SIZE;player.vy=0;player.rot=0}

  // Scroll
  cameraX+=scrollSpeed;
  score=Math.floor(cameraX/10);
  maxProgress=Math.max(maxProgress,cameraX);

  // Trail
  trail.push({x:player.x-cameraX+W/2,y:player.y+PLAYER_SIZE/2});
  if(trail.length>50)trail.shift();

  // Particles
  if(Math.random()<0.3){
    particles.push({x:player.x-cameraX+W/2+Math.random()*10-5,y:player.y+PLAYER_SIZE,vx:(Math.random()-0.5)*2,vy:Math.random()*2+1,life:30,color:player.color});
  }

  for(let i=particles.length-1;i>=0;i--){
    const p=particles[i];p.x+=p.vx;p.y+=p.vy;p.life--;
    if(p.life<=0)particles.splice(i,1);
  }

  // Check obstacles
  for(let i=0;i<obstacles.length;i++){
    const o=obstacles[i];
    const screenX=o.x-cameraX+W/2-player.x+120;
    if(screenX<0){obstacles.splice(i,1);i--;score+=10;continue}
    if(screenX<40&&screenX>-40){
      // Collision check
      const pTop=player.y,pBottom=player.y+PLAYER_SIZE;
      const pLeft=player.x-PLAYER_SIZE/2,pRight=player.x+PLAYER_SIZE/2;
      const oTop=FLOOR_Y-o.height,oBottom=FLOOR_Y;
      const oLeft=screenX+W/2-player.x+120-o.width/2,oRight=oLeft+o.width;
      if(pBottom>oTop&&pTop<oBottom&&pRight>oLeft&&pLeft<oRight){
        gameOver();break;
      }
    }
  }

  // Progress
  const totalLength=4000;
  const progress=Math.min(100,Math.round((cameraX/totalLength)*100));
  document.getElementById('scoreDisplay').textContent=score;
  document.getElementById('progressDisplay').textContent=progress+'%';
  document.getElementById('statusDisplay').textContent=progress>=100?'🎉 Complete':'▶ Playing';

  if(progress>=100){gameState='menu';if(score>highScore)highScore=score;document.getElementById('highScoreDisplay').textContent=highScore;document.getElementById('startBtn').textContent='▶ Next Level'}
}

